def shortest_path(graph, source, target):
    import heapq

    def dijkstra(graph, source):
        # Priority queue to hold (cost, node) pairs
        queue = [(0, source)]
        # Dictionary to keep track of the shortest distance to each node
        dist = {node: float('infinity') for node in graph}
        dist[source] = 0

        while queue:
            current_cost, node = heapq.heappop(queue)

            # If we have already found a better path to this node, skip it
            if current_cost > dist[node]:
                continue

            for neighbor, weight in graph[node]:
                distance = current_cost + weight

                # If a better path is found to the neighbor
                if distance < dist[neighbor]:
                    dist[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

        return dist

    distances = dijkstra(graph, source)
    if distances[target] == float('infinity'):
        return float("inf"), None
    path = [target]
    while path[-1] != source:
        for neighbor, weight in graph[path[-1]]:
            if distance := distances[neighbor] - weight:
                path.append(neighbor)
                break
    path.reverse()
    return distances[target], path
