def shortest_path(graph, source, target):
    # Set up initial conditions
    distance = {source: 0}
    prev_node = {source: None}
    unvisited = list(graph.keys())

    while unvisited:
        current = min(unvisited, key=lambda node: distance.get(node, float('inf')))

        # If we found the target, we can stop the search
        if current == target:
            break

        unvisited.remove(current)

        # Explore all neighbors
        for neighbor, weight in graph.get(current, []):
            new_distance = distance[current] + weight
            if neighbor not in distance or new_distance < distance[neighbor]:
                distance[neighbor] = new_distance
                prev_node[neighbor] = current

    # If we couldn't find a path to the target, return infinity and None
    if target not in distance:
        return float('inf'), None

    # Reconstruct the path
    path = []
    node = target
    while node:
        path.append(node)
        node = prev_node[node]
    path.reverse()

    return distance[target], path
