import heapq
from collections import defaultdict
from functools import lru_cache
from typing import Dict, List, Tuple

class Graph:
    def __init__(self, graph: Dict[int, List[Tuple[int, int]]]):
        self.graph = graph

    @lru_cache(maxsize=None)
    def shortest_path(self, source: int, target: int) -> Tuple[float, List[int]]:
        # Initialize distances and paths
        distances = {node: float('inf') for node in self.graph}
        path = {node: [] for node in self.graph}
        distances[source] = 0
        priority_queue = [(0, source)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            # Stop if the current node is the target
            if current_node == target:
                break

            # Explore neighbors
            for neighbor, weight in self.graph[current_node]:
                distance = current_distance + weight

                # Only consider the path if it's shorter
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    path[neighbor] = path[current_node] + [neighbor]
                    heapq.heappush(priority_queue, (distance, neighbor))

        # If target is unreachable, distances[target] will still be infinity
        if distances[target] == float('inf'):
            return float('inf'), None
        else:
            return distances[target], path[target]

def shortest_path(graph: Dict[int, List[Tuple[int, int]]], source: int, target: int) -> Tuple[float, List[int]]:
    return Graph(graph).shortest_path(source, target)

